using Microsoft.ML.Tokenizers;

public class TokenBudgetCalculator
{
    private readonly TiktokenTokenizer _tokenizer;

    public TokenBudgetCalculator()
    {
        // Load standard OpenAI cl100k_base (used by GPT-4 / GPT-3.5) or o200k_base (GPT-4o)
        _tokenizer = TiktokenTokenizer.CreateForModel("gpt-4o");
    }

    public int CountTokens(string text)
    {
        return _tokenizer.CountTokens(text);
    }

    public bool FitsWithinBudget(string prompt, int maxContextTokens = 8192)
    {
        int tokenCount = _tokenizer.CountTokens(prompt);
        return tokenCount <= maxContextTokens;
    }
}
